import { getMeta,setMeta } from "@/features/biblia/db";

type SelectionMode="chapter"|"range";
type StudyStep="level"|"book"|"passage";
type TextEntry={disponible:boolean;texto:string;observacion?:string}; type Comparison={epoca:string;estilo:string;matices:string[]};
type ArticulationRow={orden:string;versiculos:string;etapa:string;pregunta_guia:string;sujeto:string;verbo_central:string;desarrollo:string};
type ArcRelation={id:string;escala:"micro"|"meso"|"macro";desde:string;hasta:string;tipo:string;etiqueta:string;explicacion:string;confianza:string;revision:string};
type ArcData={unidades:Array<{id:string;escala:"micro"|"meso"|"macro";referencia:string;texto:string}>;relaciones:ArcRelation[];proposicion_dominante:string;centro:string};
type Data={titulo?:string;textos?:Record<string,TextEntry>;comprension_global?:string;comparacion_traducciones?:Record<string,Comparison|string|string[]>;lectura_comprension?:{lectura_inicial:string;conexiones:string[];oposiciones:string[];movimiento_general:string};reescritura_comparacion?:Array<{referencia:string;platense:string;torres_amat:string;observacion:string}>;delimitacion?:{unidad:string;justificacion:string};verificacion_unidad?:{inicio:string;fin:string;criterios:string[];conclusion:string};genero_literario?:{tipo:string;explicacion:string};estructura?:Array<{versiculos:string;titulo:string;explicacion:string}>;proposiciones?:Array<{texto:string;tipo:string;explicacion:string}>;analisis_proposiciones?:PropositionAnalysisData|unknown[];articulacion?:ArticulationRow[];palabras_clave?:Array<{termino:string;significado:string;funcion_en_el_texto:string}>;semantica_texto?:Array<{termino:string;versiculos:string;sentido_contextual:string;funcion_en_unidad:string}>;contexto_historico?:unknown;contexto_biblico?:unknown;mensaje_teologico?:unknown;mensaje_cristologico?:unknown;tipologia?:unknown;doctrina_catolica?:unknown;referencias_cruzadas?:Array<{referencia:string;relacion:string}>;actualizacion_pastoral?:unknown;aplicacion_espiritual?:string;preguntas_para_meditar?:string[];lectio_divina?:Record<string,string>};
type PreviewColumn={version:BibliaVersion;capitulo:number;versiculos:BibliaVersiculo[]};
type LockableScreenOrientation=ScreenOrientation&{lock?:(orientation:"landscape"|"portrait")=>Promise<void>;unlock?:()=>void};
const levelOptions=[
  {value:"pastoral" as const,label:"Pastoral",description:"Comprende el mensaje central y vívelo cada día.",ideal:"Personas que comienzan su camino de fe.",icon:Heart},
  {value:"teologico" as const,label:"Teológico",description:"Profundiza en el contexto y la estructura bíblica.",ideal:"Catequistas y personas con formación intermedia.",icon:Landmark},
  {value:"doctrinal" as const,label:"Doctrinal",description:"Estudia la enseñanza de la Iglesia y la verdad revelada.",ideal:"Personas que buscan formación sólida en la fe.",icon:Church},
  {value:"formativo" as const,label:"Formativo",description:"Aprende y enseña mediante objetivos, actividades y evaluación.",ideal:"Formadores, líderes y agentes de pastoral.",icon:Users},
];
export default function BibliaEstudio(){const {id}=useParams();const nav=useNavigate();const [params]=useSearchParams();const initialBook=(params.get("libro")||"").toUpperCase();const initialChapter=initialBook?Math.max(1,Number(params.get("cap")||1)):0;const [level,setLevel]=useState<StudyLevel|null>(null);const [study,setStudy]=useState<BibleStudy|null>(null);const [books,setBooks]=useState<BibliaLibro[]>([]);const [book,setBook]=useState(initialBook);const [chapter,setChapter]=useState(initialChapter);const [selectionMode,setSelectionMode]=useState<SelectionMode>("range");const [rangeAnchor,setRangeAnchor]=useState<number|null>(null);const [start,setStart]=useState(1);const [end,setEnd]=useState(5);const [preview,setPreview]=useState<PreviewColumn[]>([]);const [previewLoading,setPreviewLoading]=useState(Boolean(initialBook));const [comparisonRequested,setComparisonRequested]=useState(Boolean(id));const [tab,setTab]=useState<Tab>("Texto");const [loading,setLoading]=useState(Boolean(id));const [configured,setConfigured]=useState<boolean|null>(null);const [ready,setReady]=useState<boolean|null>(null);const [error,setError]=useState("");
const [authenticated,setAuthenticated]=useState<boolean|null>(null);
const [recentStudies,setRecentStudies]=useState<RecentBibleStudy[]>([]);
const [showAllRecent,setShowAllRecent]=useState(false);
const [studyStep,setStudyStep]=useState<StudyStep>("level");
const [studyComparisonOpen,setStudyComparisonOpen]=useState(false);
const [restoringPortrait,setRestoringPortrait]=useState(false);
const [recoveringGeneration,setRecoveringGeneration]=useState(false);
const generationRecoveryRef=useRef<AbortController|null>(null);
useEffect(()=>()=>generationRecoveryRef.current?.abort(),[]);
useEffect(()=>{getBibliaCatalogo().then(x=>setBooks(x.libros)).catch(e=>setError(e.message));getStudyStatus().then(x=>{setConfigured(Boolean(x.configured));setReady(Boolean(x.ready));}).catch(()=>{setConfigured(false);setReady(false);});},[]);
useEffect(()=>{let active=true;const syncSession=async(session:unknown)=>{if(!active)return;if(!session){setAuthenticated(false);setRecentStudies([]);return;}setAuthenticated(null);try{const studies=await getRecentBibleStudies();if(!active)return;setRecentStudies(studies);setAuthenticated(true);}catch{if(!active)return;setRecentStudies([]);setAuthenticated(false);}};void bibleStudyAuth.auth.getSession().then(({data})=>syncSession(data.session));const {data}=bibleStudyAuth.auth.onAuthStateChange((_event,session)=>{void syncSession(session);});return()=>{active=false;data.subscription.unsubscribe();};},[]);
useEffect(()=>{if(!book||chapter<1){setPreview([]);setPreviewLoading(false);return;}let active=true;setPreviewLoading(true);getBibliaVersiones().then(async versions=>{const normalized=(version:BibliaVersion)=>`${version.codigo} ${version.nombre}`.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toUpperCase();const pick=(codes:string[],names:string[])=>versions.find(version=>codes.includes(version.codigo.toUpperCase()))||versions.find(version=>names.some(name=>normalized(version).includes(name)));const preferred=[pick(["SPAPLATENSE"],["PLATENSE","STRAUBINGER"]),pick(["TORRESAMAT","TORRES_AMAT"],["TORRES AMAT"]),pick(["SCIO"],["SCIO","SAN MIGUEL"])].filter((version):version is BibliaVersion=>Boolean(version));const comparable=preferred.flatMap(version=>{const equivalentChapter=equivalentChapterFromPlatense(book,chapter,version);return equivalentChapter===null?[]:[{version,chapter:equivalentChapter}];});const results=await Promise.allSettled(comparable.map(item=>getBibliaCapitulo(book,item.chapter,item.version.codigo)));if(!active)return;setPreview(results.flatMap(result=>result.status==="fulfilled"?[{version:result.value.version,capitulo:result.value.capitulo,versiculos:result.value.versiculos}]:[]));}).catch(()=>active&&setPreview([])).finally(()=>active&&setPreviewLoading(false));return()=>{active=false;};},[book,chapter]);
useEffect(()=>{if(!id)return;setLoading(true);getBibleStudy(Number(id)).then(result=>{setStudy(result);setLevel(result.nivel);if(result.libro_codigo)setBook(result.libro_codigo.toUpperCase());if(result.capitulo_inicio)setChapter(result.capitulo_inicio);if(result.versiculo_inicio)setStart(result.versiculo_inicio);if(result.versiculo_fin)setEnd(result.versiculo_fin);setComparisonRequested(true);}).catch(e=>setError(e.message)).finally(()=>setLoading(false));},[id]);
const generate=async()=>{const firstVerse=verseOptions[0];const lastVerse=verseOptions[verseOptions.length-1];const selectedStart=selectionMode==="chapter"?firstVerse:start;const selectedEnd=selectionMode==="chapter"?lastVerse:end;if(!level||!book||chapter<1||!selectedStart||!selectedEnd){setError("Selecciona un nivel y un pasaje válido.");return;}const input={libro_codigo:book,capitulo_inicio:chapter,versiculo_inicio:selectedStart,capitulo_fin:chapter,versiculo_fin:selectedEnd,nivel:level};setStart(selectedStart);setEnd(selectedEnd);setComparisonRequested(true);setLoading(true);setRecoveringGeneration(false);setError("");generationRecoveryRef.current?.abort();const recoveryController=new AbortController();generationRecoveryRef.current=recoveryController;try{let result: BibleStudy;try{result=await createBibleStudy(input);}catch(e){if(!isInterruptedBibleStudyGeneration(e))throw e;setRecoveringGeneration(true);const reference=e as Error&{studyId?:number;generationId?:number};const recovered=await recoverGeneratedBibleStudy(input,{signal:recoveryController.signal,studyId:reference.studyId,generationId:reference.generationId});if(!recovered)throw new Error("El estudio continúa procesándose. Revísalo en Consultados recientemente dentro de unos momentos.");result=recovered;}setStudy(result);void getRecentBibleStudies().then(setRecentStudies).catch(()=>undefined);nav(`/biblia/estudio/${result.id}`,{replace:true});}catch(e){if(e instanceof DOMException&&e.name==="AbortError")return;const msg=e instanceof Error?e.message:"";if(msg==="AUTH_REQUIRED")nav(`/acceso?next=${encodeURIComponent(`/biblia/estudio?libro=${book}&cap=${chapter}`)}`);else setError(msg);}finally{if(generationRecoveryRef.current===recoveryController)generationRecoveryRef.current=null;setRecoveringGeneration(false);setLoading(false);}};
const verseOptions=useMemo(()=>{const primaryColumn=preview.find(column=>column.version.codigo.toUpperCase().includes("SPAPLATENSE"))||preview[0];return (primaryColumn?.versiculos||[]).map(verse=>verse.versiculo);},[preview]);
const selectRangeVerse=(value:number)=>{setComparisonRequested(false);if(rangeAnchor===null){setStart(value);setEnd(value);setRangeAnchor(value);return;}setStart(Math.min(rangeAnchor,value));setEnd(Math.max(rangeAnchor,value));setRangeAnchor(null);};
const selectedBook=books.find(item=>item.codigo===book);
const hasStudyContent=Boolean(study&&study.estado!=="error"&&Object.keys(study.contenido||{}).length>0);
const quotaReached=error==="Has utilizado tus estudios nuevos disponibles para este mes.";
useEffect(()=>{if(verseOptions.length===0)return;const first=verseOptions[0];const last=verseOptions[verseOptions.length-1];if(selectionMode==="chapter"){if(start!==first)setStart(first);if(end!==last)setEnd(last);return;}const nextStart=verseOptions.includes(start)?start:first;const nextEnd=verseOptions.includes(end)&&end>=nextStart?end:(verseOptions[Math.min(4,verseOptions.length-1)]??nextStart);if(nextStart!==start)setStart(nextStart);if(nextEnd!==end)setEnd(nextEnd);},[verseOptions,selectionMode,start,end]);
useEffect(()=>{const restore=()=>{if(!document.fullscreenElement)(screen.orientation as LockableScreenOrientation|undefined)?.unlock?.();};document.addEventListener("fullscreenchange",restore);return()=>{document.removeEventListener("fullscreenchange",restore);(screen.orientation as LockableScreenOrientation|undefined)?.unlock?.();};},[]);
useEffect(()=>{const portrait=window.matchMedia("(orientation: portrait)");const sync=()=>{if(portrait.matches){setRestoringPortrait(false);(screen.orientation as LockableScreenOrientation|undefined)?.unlock?.();}};sync();portrait.addEventListener?.("change",sync);return()=>portrait.removeEventListener?.("change",sync);},[]);
const openComparison=async()=>{setComparisonRequested(true);window.setTimeout(()=>document.getElementById("bible-comparison-view")?.scrollIntoView({behavior:"smooth",block:"start"}),0);if(!window.matchMedia("(max-width: 767px)").matches)return;try{await (screen.orientation as LockableScreenOrientation|undefined)?.lock?.("landscape");}catch{/* La orientación manual y el diseño adaptable permanecen disponibles. */}};
const closeComparison=()=>{setComparisonRequested(false);(screen.orientation as LockableScreenOrientation|undefined)?.unlock?.();};
const selectStudyTab=async(nextTab:Tab)=>{setTab(nextTab);const mobile=window.matchMedia("(max-width: 767px)").matches;if(nextTab==="Comparación"&&mobile){setStudyComparisonOpen(true);setRestoringPortrait(false);try{await (screen.orientation as LockableScreenOrientation|undefined)?.lock?.("landscape");}catch{/* El modal sigue siendo independiente y responde al giro manual. */}return;}setStudyComparisonOpen(false);(screen.orientation as LockableScreenOrientation|undefined)?.unlock?.();};
const closeStudyComparison=async()=>{setTab("Texto");setStudyComparisonOpen(false);const landscape=window.matchMedia("(orientation: landscape)").matches;if(landscape)setRestoringPortrait(true);const orientation=screen.orientation as LockableScreenOrientation|undefined;orientation?.unlock?.();if(landscape){try{await orientation?.lock?.("portrait");}catch{/* Al girar manualmente a vertical se restaura la navegación. */}}};
const continueStudyComparison=async()=>{setTab("Estructura");setStudyComparisonOpen(false);const landscape=window.matchMedia("(orientation: landscape)").matches;if(landscape)setRestoringPortrait(true);const orientation=screen.orientation as LockableScreenOrientation|undefined;orientation?.unlock?.();if(landscape){try{await orientation?.lock?.("portrait");}catch{/* Al girar manualmente a vertical se restaura la navegación. */}}};
return <BibliaLayout title="Estudio Bíblico" back="/biblia" hideBottomNav={studyComparisonOpen||restoringPortrait} headerAction={hasStudyContent?<button type="button" onClick={()=>document.querySelector<HTMLButtonElement>(".study-reader-host > section > .sticky button")?.click()} className="flex h-10 min-w-10 items-center justify-center rounded-full border border-[#D4AF37]/35 bg-[#111111] px-2 font-display text-lg text-[#F2D27A] shadow-[0_0_18px_rgba(212,175,55,0.12)]" aria-label="Formato de lectura">Aa</button>:undefined}>
  {!hasStudyContent&&!loading&&studyStep==="level"&&<>
    <IntroStudyCard/>
    <RecentStudies studies={recentStudies} expanded={showAllRecent} onToggle={()=>setShowAllRecent(value=>!value)}/>
    <section aria-labelledby="study-level-heading" className="mb-4 rounded-[1.35rem] border border-[#D4AF37]/25 bg-[#0B0B0B] p-4 sm:p-5">
      {ready===false&&<p className="mb-4 rounded-xl border border-[#D4AF37]/20 bg-[#D4AF37]/10 p-3 text-sm text-[#F2D27A]">{configured===false?"Servicio de estudio no configurado.":"Los nuevos estudios estarán disponibles cuando finalice la revisión de equivalencias bíblicas."} Los estudios existentes continúan disponibles.</p>}
      <h2 id="study-level-heading" className="mt-3 font-display text-lg text-[#F8F5EA]">Selecciona tu nivel</h2>
      <div className="mt-4 grid grid-cols-1 gap-3 sm:grid-cols-2">{levelOptions.map(option=>{const Icon=option.icon;const selected=level===option.value;return <button key={option.value} type="button" aria-pressed={selected} onClick={()=>{setLevel(option.value);setStudy(null);setComparisonRequested(false);setError("");setStudyStep(initialBook?"passage":"book");}} className={`group relative min-h-11 rounded-2xl border p-4 text-left outline-none transition focus-visible:ring-2 focus-visible:ring-[#F2D27A] focus-visible:ring-offset-2 focus-visible:ring-offset-[#050505] ${selected?"border-[#D4AF37] bg-[#D4AF37]/12 shadow-[0_0_24px_rgba(212,175,55,0.12)]":"border-[#D4AF37]/25 bg-[#111] hover:border-[#D4AF37]/60 hover:bg-[#D4AF37]/8"}`}><span className="flex items-start gap-3"><span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full border border-[#D4AF37]/35 bg-[#D4AF37]/10 text-[#D4AF37]"><Icon className="h-5 w-5" aria-hidden="true"/></span><span className="min-w-0 flex-1"><strong className="block font-display text-lg text-[#F8F5EA]">{option.label}</strong><span className="mt-1 block text-sm leading-snug text-[#C9C3B3]">{option.description}</span></span><ChevronRight className={`mt-2 h-4 w-4 shrink-0 transition ${selected?"text-[#F2D27A]":"text-[#8F897C] group-hover:translate-x-0.5 group-hover:text-[#D4AF37]"}`} aria-hidden="true"/></span><span className="mt-3 block border-t border-[#D4AF37]/15 pt-3 text-xs leading-relaxed text-[#D4AF37]"><span className="font-semibold">Ideal para:</span> {option.ideal}</span></button>})}</div>
    </section>
  </>}
  {!hasStudyContent&&!loading&&studyStep==="book"&&<section aria-labelledby="study-book-heading" className="mb-4 rounded-[1.35rem] border border-[#D4AF37]/25 bg-[#0B0B0B] p-4 sm:p-5">
    <FlowBackButton label="Volver a niveles" onClick={()=>setStudyStep("level")}/>
    <h1 id="study-book-heading" className="mt-3 font-display text-xl text-[#F8F5EA]">Libros</h1>
    <div className="mt-3"><BibliaPassageGridSelector stage="book" books={books} book={book} chapter={chapter} onBookChange={(value)=>{setBook(value);setChapter(0);setStart(1);setEnd(5);setRangeAnchor(null);setComparisonRequested(false);setStudyStep("passage");}} onChapterChange={()=>undefined}/></div>
  </section>}
  {!hasStudyContent&&!loading&&studyStep==="passage"&&<section aria-labelledby="study-passage-heading" className="mb-4 rounded-[1.35rem] border border-[#D4AF37]/25 bg-[#0B0B0B] p-4 sm:p-5">
    <FlowBackButton label="Volver a libros" onClick={()=>setStudyStep("book")}/>
    <h1 id="study-passage-heading" className="mt-3 font-display text-xl text-[#F8F5EA]">{selectedBook?.nombre||"Pasaje"}</h1>
    <div className="mt-3"><BibliaPassageGridSelector stage="chapter" books={books} book={book} chapter={chapter} onBookChange={()=>undefined} onChapterChange={(value)=>{setChapter(value);setStart(1);setEnd(5);setRangeAnchor(null);setComparisonRequested(false);}}/></div>
    {chapter>0&&<><div className="mt-5 grid grid-cols-2 gap-2 rounded-xl border border-[#D4AF37]/20 bg-[#111] p-1"><button type="button" onClick={()=>{setSelectionMode("chapter");setRangeAnchor(null);setComparisonRequested(false);}} className={`min-h-11 rounded-lg px-3 py-2 text-xs font-semibold outline-none focus-visible:ring-2 focus-visible:ring-[#F2D27A] ${selectionMode==="chapter"?"bg-[#D4AF37] text-black":"text-[#C9C3B3]"}`}>Capítulo completo</button><button type="button" onClick={()=>{setSelectionMode("range");setRangeAnchor(null);setComparisonRequested(false);}} className={`min-h-11 rounded-lg px-3 py-2 text-xs font-semibold outline-none focus-visible:ring-2 focus-visible:ring-[#F2D27A] ${selectionMode==="range"?"bg-[#D4AF37] text-black":"text-[#C9C3B3]"}`}>Elegir versículos</button></div>
    {previewLoading?<div className="flex justify-center py-5"><Loader2 className="h-5 w-5 animate-spin text-[#D4AF37]"/></div>:<VerseGrid values={verseOptions} start={start} end={end} mode={selectionMode} awaitingEnd={rangeAnchor!==null} onSelect={selectRangeVerse}/>}
    {authenticated===true?<button disabled={previewLoading||preview.length===0} onClick={generate} className="mt-5 flex min-h-11 w-full items-center justify-center gap-2 rounded-xl bg-gradient-to-r from-[#D4AF37] to-[#F2D27A] py-3 font-bold text-black shadow-[0_14px_32px_rgba(212,175,55,0.2)] outline-none focus-visible:ring-2 focus-visible:ring-[#F8F5EA] disabled:cursor-not-allowed disabled:opacity-40">Consultar estudio {levelOptions.find(item=>item.value===level)?.label}<ChevronRight className="h-4 w-4"/></button>:<button disabled={authenticated===null||previewLoading||preview.length===0} onClick={openComparison} className="mt-5 flex min-h-11 w-full items-center justify-center gap-2 rounded-xl border border-[#D4AF37]/45 bg-[#D4AF37]/10 py-3 font-bold text-[#F2D27A] outline-none focus-visible:ring-2 focus-visible:ring-[#F2D27A] disabled:opacity-40">Comparar versiones<ChevronRight className="h-4 w-4"/></button>}</>}
  </section>}  {!hasStudyContent&&comparisonRequested&&preview.length>0&&<ComparisonPreview columns={preview} start={start} end={end} onClose={closeComparison}/>}
  {comparisonRequested&&authenticated===false&&<GuestStudyPrompt next={`/biblia/estudio?libro=${book}&cap=${chapter}`}/>}
  {loading&&<Generating recovering={recoveringGeneration}/>}
  {error&&<div role="alert" className={`mb-4 rounded-2xl border p-4 text-sm ${quotaReached?"border-amber-400/35 bg-amber-950/20 text-amber-100":"border-red-500/30 bg-red-950/20 text-red-200"}`}><p className="font-semibold">{quotaReached?"Cupo mensual agotado":error||"No fue posible generar el estudio en este momento."}</p>{quotaReached?<p className="mt-1 text-amber-100/80">Podrás solicitar nuevos estudios el próximo mes. Los estudios existentes continúan disponibles sin consumir cupo.</p>:<button onClick={()=>id?location.reload():generate()} className="mt-3 rounded-lg border border-red-300/30 px-3 py-2">Intentar nuevamente</button>}</div>}
  {hasStudyContent&&study&&<><div className="study-reader-host"><StudyReadingFrameV2><StudyView study={study} tab={tab} setTab={(nextTab)=>void selectStudyTab(nextTab)}/>{tab==="Comparación"&&<VerseComparisonTable rows={(study.contenido as {comparacion_versiculos?:VerseComparison[]}).comparacion_versiculos} onClose={closeStudyComparison} onNext={continueStudyComparison}/>}</StudyReadingFrameV2></div><SupportCard/></>}
</BibliaLayout>}

type StudyReadingTheme="oscuro"|"claro"|"sepia";
type StudyReadingFont="literata"|"georgia"|"garamond"|"atkinson"|"sans";
type StudyReadingAlignment="izquierda"|"justificada";
type StudyReadingPrefs={tam:number;tema:StudyReadingTheme;fuente?:StudyReadingFont|"bookerly";pesoFuente?:number;interlineado?:number;alineacion?:StudyReadingAlignment;margenLectura?:"estrecho"|"normal"|"amplio"};
const studyFonts=[
  {id:"literata" as const,name:"Literata",family:"'Literata', Georgia, serif"},
  {id:"georgia" as const,name:"Georgia",family:"Georgia, 'Times New Roman', serif"},
  {id:"garamond" as const,name:"Garamond",family:"'EB Garamond', Garamond, serif"},
  {id:"atkinson" as const,name:"Atkinson",family:"'Atkinson Hyperlegible', Arial, sans-serif"},
  {id:"sans" as const,name:"Moderna",family:"'Montserrat', system-ui, sans-serif"},
];
function StudyReadingFrame({children}:{children:React.ReactNode}){const [open,setOpen]=useState(false);const [prefs,setPrefs]=useState<Required<Omit<StudyReadingPrefs,"margenLectura">>>({tam:17,tema:"oscuro",fuente:"literata",pesoFuente:400,interlineado:1.9,alineacion:"izquierda"});useEffect(()=>{void getMeta<StudyReadingPrefs>("prefsLectura").then(saved=>{if(!saved)return;setPrefs({tam:saved.tam??17,tema:saved.tema??"oscuro",fuente:!saved.fuente||saved.fuente==="bookerly"?"literata":saved.fuente,pesoFuente:saved.pesoFuente??400,interlineado:saved.interlineado??1.9,alineacion:saved.alineacion??"izquierda"});});},[]);const save=(next:Partial<typeof prefs>)=>{const value={...prefs,...next};setPrefs(value);void getMeta<StudyReadingPrefs>("prefsLectura").then(current=>setMeta("prefsLectura",{...(current||{}),...value}));};const font=studyFonts.find(item=>item.id===prefs.fuente)??studyFonts[0];const theme=prefs.tema==="claro"?"border-[#D4AF37]/30 bg-[#F8F5EA] text-[#17140d]":prefs.tema==="sepia"?"biblia-eink-paper border-[#5f5b4d]/30 text-[#20211d]":"border-[#D4AF37]/20 bg-[#0B0B0B] text-[#F8F5EA]";return <section className="mb-4"><div className="sticky top-2 z-30 mb-3 flex justify-end"><button type="button" onClick={()=>setOpen(value=>!value)} aria-expanded={open} className="flex min-h-11 min-w-11 items-center justify-center rounded-full border border-[#D4AF37]/40 bg-[#0B0B0B]/95 px-3 font-display text-xl text-[#F2D27A] shadow-lg backdrop-blur">Aa</button></div>{open&&<div className="relative z-20 mb-3 rounded-2xl border border-[#D4AF37]/30 bg-[#0B0B0B] p-3 text-[#F8F5EA] shadow-2xl"><div className="mb-3 flex items-center justify-between"><strong className="text-sm text-[#F2D27A]">Formato de lectura</strong><button type="button" onClick={()=>setOpen(false)} className="flex h-10 w-10 items-center justify-center" aria-label="Cerrar formato"><X className="h-4 w-4"/></button></div><div className="grid gap-4 sm:grid-cols-2"><div><span className="mb-2 block text-xs text-[#C9C3B3]">Tema</span><div className="grid grid-cols-3 gap-2">{(["claro","oscuro","sepia"] as StudyReadingTheme[]).map(themeOption=><button type="button" key={themeOption} onClick={()=>save({tema:themeOption})} className={`min-h-11 rounded-lg border text-xs capitalize ${prefs.tema===themeOption?"border-[#D4AF37] bg-[#D4AF37]/15 text-[#F2D27A]":"border-white/15 text-[#C9C3B3]"}`}>{themeOption==="sepia"?"Tinta":themeOption}</button>)}</div></div><div><span className="mb-2 block text-xs text-[#C9C3B3]">Tipo de letra</span><div className="grid grid-cols-2 gap-2">{studyFonts.map(option=><button type="button" key={option.id} onClick={()=>save({fuente:option.id})} style={{fontFamily:option.family}} className={`flex min-h-11 items-center justify-between rounded-lg border px-3 text-xs ${prefs.fuente===option.id?"border-[#D4AF37] bg-[#D4AF37]/15 text-[#F2D27A]":"border-white/15 text-[#C9C3B3]"}`}>{option.name}{prefs.fuente===option.id&&<Check className="h-3.5 w-3.5"/>}</button>)}</div></div><div><span className="mb-2 block text-xs text-[#C9C3B3]">Tamaño · {prefs.tam}px</span><div className="flex items-center gap-3"><button type="button" onClick={()=>save({tam:Math.max(13,prefs.tam-1)})} className="h-11 w-11 rounded-lg border border-white/15 text-xl">−</button><input type="range" min="13" max="26" value={prefs.tam} onChange={event=>save({tam:Number(event.target.value)})} className="min-w-0 flex-1 accent-[#D4AF37]"/><button type="button" onClick={()=>save({tam:Math.min(26,prefs.tam+1)})} className="h-11 w-11 rounded-lg border border-white/15 text-xl">+</button></div></div><div><span className="mb-2 block text-xs text-[#C9C3B3]">Alineación</span><div className="grid grid-cols-2 gap-2"><button type="button" onClick={()=>save({alineacion:"izquierda"})} className={`flex min-h-11 items-center justify-center gap-2 rounded-lg border text-xs ${prefs.alineacion==="izquierda"?"border-[#D4AF37] text-[#F2D27A]":"border-white/15 text-[#C9C3B3]"}`}><AlignLeft className="h-4 w-4"/>Izquierda</button><button type="button" onClick={()=>save({alineacion:"justificada"})} className={`flex min-h-11 items-center justify-center gap-2 rounded-lg border text-xs ${prefs.alineacion==="justificada"?"border-[#D4AF37] text-[#F2D27A]":"border-white/15 text-[#C9C3B3]"}`}><AlignJustify className="h-4 w-4"/>Justificada</button></div></div></div></div>}<article style={{fontFamily:font.family,fontSize:prefs.tam,lineHeight:prefs.interlineado,fontWeight:prefs.pesoFuente,textAlign:prefs.alineacion==="justificada"?"justify":"left"}} className={`mx-auto rounded-[1.5rem] border p-3 transition-colors sm:p-5 [&>div]:!bg-transparent [&>section]:!bg-transparent [&_p]:!text-inherit [&_li]:!text-inherit [&_td]:!text-inherit ${theme}`}>{children}</article></section>}

function FlowBackButton({label,onClick}:{label:string;onClick:()=>void}){return <button type="button" onClick={onClick} className="inline-flex min-h-9 items-center gap-1.5 rounded-lg px-1 text-xs font-semibold text-[#F2D27A] outline-none transition hover:text-[#FFF1B8] focus-visible:ring-2 focus-visible:ring-[#F2D27A]"><ArrowLeft className="h-4 w-4" aria-hidden="true"/>{label}</button>}

function IntroStudyCard(){return <section aria-labelledby="study-intro-title" className="mb-3 overflow-hidden rounded-[1.35rem] border border-[#D4AF37]/35 bg-[radial-gradient(circle_at_50%_0%,rgba(212,175,55,0.14),transparent_55%),#0B0B0B] p-4"><div className="flex items-center gap-3"><span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-full border border-[#D4AF37]/45 bg-[#D4AF37]/10 text-[#D4AF37] shadow-[0_0_24px_rgba(212,175,55,0.12)]"><BookOpen className="h-6 w-6" aria-hidden="true"/></span><div><h1 id="study-intro-title" className="font-display text-lg leading-tight text-[#F8F5EA]">Profundiza en la Palabra</h1><p className="mt-1 text-xs leading-relaxed text-[#C9C3B3] sm:text-sm">Elige tu nivel y continúa tu camino de formación.</p></div></div></section>}

function RecentStudies({studies,expanded,onToggle}:{studies:RecentBibleStudy[];expanded:boolean;onToggle:()=>void}){const visible=expanded?studies:studies.slice(0,3);return <section aria-labelledby="recent-studies-title" className="mb-4 rounded-[1.35rem] border border-[#D4AF37]/25 bg-[#0B0B0B] p-4"><div className="flex items-center justify-between gap-3"><h2 id="recent-studies-title" className="font-display text-base leading-tight text-[#F8F5EA] sm:text-lg">Consultados recientemente</h2><button type="button" onClick={onToggle} className="inline-flex min-h-11 shrink-0 items-center gap-1 rounded-lg px-1.5 text-xs font-semibold text-[#D4AF37] sm:px-2 sm:text-sm outline-none hover:text-[#F2D27A] focus-visible:ring-2 focus-visible:ring-[#F2D27A]">{expanded?"Ver menos":"Ver todos"}<ChevronRight className={`h-4 w-4 transition ${expanded?"rotate-90":""}`} aria-hidden="true"/></button></div>{visible.length===0?<div className="mt-3 rounded-xl border border-dashed border-[#D4AF37]/20 bg-[#111]/70 p-4 text-center"><BookOpen className="mx-auto h-6 w-6 text-[#D4AF37]/70" aria-hidden="true"/><p className="mt-2 text-sm text-[#C9C3B3]">Aún no has consultado estudios.</p></div>:<div className="mt-3 space-y-2">{visible.map(item=><Link key={item.id} to={`/biblia/estudio/${item.id}`} className="group flex min-h-16 items-center gap-3 rounded-xl border border-white/10 bg-[#111] p-3 outline-none transition hover:border-[#D4AF37]/50 hover:bg-[#D4AF37]/5 focus-visible:ring-2 focus-visible:ring-[#F2D27A]"><span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-[#D4AF37]/10 text-[#D4AF37]"><BookOpen className="h-5 w-5" aria-hidden="true"/></span><span className="min-w-0 flex-1"><strong className="block truncate text-sm text-[#F8F5EA]">{item.referencia||item.titulo}</strong><span className="mt-0.5 block text-xs text-[#D4AF37]">Nivel {levelOptions.find(option=>option.value===item.nivel)?.label||"Formador"}</span></span><ChevronRight className="h-5 w-5 shrink-0 text-[#8F897C] transition group-hover:translate-x-0.5 group-hover:text-[#D4AF37]" aria-hidden="true"/></Link>)}</div>}</section>}
function VerseGrid({values,start,end,mode,awaitingEnd,onSelect}:{values:number[];start:number;end:number;mode:SelectionMode;awaitingEnd:boolean;onSelect:(value:number)=>void}){return <div className="mt-4 rounded-xl border border-[#D4AF37]/20 bg-[#111] p-3"><div className="mb-3 flex items-center justify-between gap-3 text-xs"><span className="font-semibold text-[#D4AF37]">{mode==="chapter"?"Se estudiará todo el capítulo":awaitingEnd?"Ahora selecciona el último versículo":"Selecciona el primer versículo"}</span><span className="text-[#C9C3B3]">{start===end?`Versículo ${start}`:`Versículos ${start}–${end}`}</span></div><div className="grid grid-cols-6 gap-2 sm:grid-cols-8">{values.map(value=>{const selected=mode==="chapter"||(value>=start&&value<=end);const boundary=mode==="range"&&(value===start||value===end);return <button key={value} type="button" disabled={mode==="chapter"} onClick={()=>onSelect(value)} aria-pressed={selected} className={`aspect-square rounded-lg border text-sm font-semibold transition ${selected?"border-[#D4AF37] bg-[#D4AF37]/20 text-[#F2D27A]":"border-white/10 bg-black/30 text-[#C9C3B3] hover:border-[#D4AF37]/50"} ${boundary?"ring-2 ring-[#F2D27A]/70":""} disabled:cursor-default`}>{value}</button>;})}</div></div>}

function GuestStudyPrompt({next}:{next:string}){return <aside className="mb-4 rounded-[1.35rem] border border-[#D4AF37]/30 bg-[#0B0B0B] p-5 text-center"><BookOpen className="mx-auto h-7 w-7 text-[#D4AF37]"/><h2 className="mt-3 font-display text-xl text-[#F8F5EA]">Continúa con el estudio bíblico</h2><p className="mt-2 text-sm leading-relaxed text-[#C9C3B3]">Para generar estudios nuevos necesitas una cuenta gratuita. Esto protege el servicio, permite aplicar correctamente el cupo mensual y conserva tu historial para cuando regreses.</p><p className="mt-2 text-xs leading-relaxed text-[#8F897C]">La lectura y la comparación bíblica continúan disponibles sin registrarte.</p><Link to={`/acceso?next=${encodeURIComponent(next)}`} className="mt-4 inline-flex min-h-11 items-center justify-center rounded-xl bg-[#D4AF37] px-5 text-sm font-bold text-black">Registrarme o iniciar sesión</Link></aside>}

function SupportCard(){return <aside className="mt-4 rounded-[1.35rem] border border-[#D4AF37]/20 bg-[#0B0B0B] p-4"><div className="flex items-start gap-3"><span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-[#D4AF37]/10 text-[#D4AF37]"><HandHeart className="h-5 w-5"/></span><div><h2 className="font-display text-lg text-[#F8F5EA]">Ayúdanos a sostener esta misión</h2><p className="mt-1 text-sm leading-relaxed text-[#C9C3B3]">Los estudios publicados permanecen disponibles gratuitamente. Tu aporte voluntario ayuda a preparar nuevos recursos de evangelización.</p><Link to="/donar" className="mt-3 inline-flex rounded-lg border border-[#D4AF37]/35 px-3 py-2 text-xs font-bold text-[#D4AF37]">Apoyar La Voz de Jesús</Link></div></div></aside>}

function Generating({recovering=false}:{recovering?:boolean}){const steps=recovering?["Solicitud recibida","Preparando contexto","Generando estudio","Preparando resultado"]:["Solicitud recibida","Preparando contexto","Generando estudio","Preparando resultado"];return <div className="rounded-[1.5rem] border border-[#D4AF37]/25 bg-[#0B0B0B] p-6"><div className="text-center"><Loader2 className="mx-auto h-8 w-8 animate-spin text-[#D4AF37]"/><h2 className="mt-4 font-display text-xl">Generando tu estudio</h2></div><ol className="mx-auto mt-5 max-w-sm space-y-3 text-sm">{steps.map((step,index)=><li key={step} className="flex items-center gap-3"><span className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-full border ${index<2?"border-[#D4AF37] text-[#D4AF37]":"border-white/25 text-[#8F897C]"}`}>{index<2?"✓":index===2?<Loader2 className="h-3.5 w-3.5 animate-spin"/>:"○"}</span><span className={index<=2?"text-[#F8F5EA]":"text-[#8F897C]"}>{step}</span></li>)}</ol><p className="mt-5 rounded-xl border border-[#D4AF37]/15 p-3 text-center text-xs leading-relaxed text-[#C9C3B3]">Puedes continuar usando la aplicación. Recuperaremos el estudio cuando esté disponible.</p></div>}
const keywordStyles=["border-amber-300/80 bg-amber-300/20 text-amber-100","border-cyan-300/80 bg-cyan-300/20 text-cyan-100","border-rose-300/80 bg-rose-300/20 text-rose-100","border-emerald-300/80 bg-emerald-300/20 text-emerald-100","border-violet-300/80 bg-violet-300/20 text-violet-100","border-orange-300/80 bg-orange-300/20 text-orange-100"];
const semanticFamilies:Record<string,string>={misericordia:"misericordia",misericordioso:"misericordia",compasion:"misericordia",compasivo:"misericordia",clemencia:"misericordia",piedad:"misericordia",senor:"dios",yahve:"dios",dios:"dios",cristo:"cristo",jesucristo:"cristo",mesias:"cristo",salvar:"salvacion",salvacion:"salvacion",salvador:"salvacion",justicia:"justicia",justo:"justicia",inocente:"inocencia",inocencia:"inocencia",culpa:"culpa",culpable:"culpa",santo:"santidad",santidad:"santidad",gloria:"gloria",glorioso:"gloria",amor:"amor",caridad:"amor",amar:"amor",reino:"reino",rey:"reino",alianza:"alianza",pacto:"alianza",perdon:"perdon",perdonar:"perdon",gracia:"gracia",verdad:"verdad",vida:"vida",muerte:"muerte",corazon:"corazon",espiritu:"espiritu",dolor:"sufrimiento",sufrir:"sufrimiento",sufrimiento:"sufrimiento",angustia:"angustia",angustiado:"angustia",amargura:"angustia",tristeza:"angustia",esperar:"esperanza",esperanza:"esperanza",sabio:"sabiduria",sabiduria:"sabiduria",silencio:"silencio",callar:"silencio"};
const stopWords=new Set(["aquel","aquella","aquellos","aunque","como","cuando","donde","entre","hacia","hasta","para","pero","porque","sobre","tambien","tiene","todos","todas","desde","esta","este","estos","estas","ellos","ellas","quien","cual","seran","habia","hacer","hecho","pues","sino","muy"]);
function lexicalKey(word:string){const normalized=word.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-zñ]/g,"");if(!normalized)return "";if(semanticFamilies[normalized])return semanticFamilies[normalized];const singular=normalized.length>6&&normalized.endsWith("es")?normalized.slice(0,-2):normalized.length>5&&normalized.endsWith("s")?normalized.slice(0,-1):normalized;return singular.length>=5&&!stopWords.has(singular)?singular:"";}
function sharedKeywords(columns:PreviewColumn[],start:number,end:number){const byVersion=new Map<string,Set<string>>();const firstVerse=new Map<string,number>();columns.forEach(column=>{const keys=new Set<string>();column.versiculos.filter(v=>v.versiculo>=start&&v.versiculo<=end).forEach(v=>v.texto.split(/\s+/).forEach(word=>{const key=lexicalKey(word);if(key){keys.add(key);firstVerse.set(key,Math.min(firstVerse.get(key)??v.versiculo,v.versiculo));}}));byVersion.set(column.version.codigo,keys);});const frequency=new Map<string,number>();byVersion.forEach(keys=>keys.forEach(key=>frequency.set(key,(frequency.get(key)||0)+1)));const phaseCounts=[0,0,0];return new Map([...frequency.entries()].filter(([,count])=>count>=2).map(([key])=>{const ratio=end===start?0:(firstVerse.get(key)!-start)/(end-start);const phase=ratio<0.34?0:ratio<0.67?1:2;const palettes=[[0,5],[1,4],[3,2]];const color=palettes[phase][phaseCounts[phase]++%2];return [key,color];}));}
function keywordPhase(color:number){return color===0||color===5?"Apertura":color===1||color===4?"Desarrollo":"Cierre";}
function HighlightedVerse({text,keywords}:{text:string;keywords:Map<string,number>}){return <>{text.split(/(\p{L}+)/gu).map((part,index)=>{const color=keywords.get(lexicalKey(part));return color===undefined?part:<mark key={index} className={`rounded-sm border-b px-0.5 ${keywordStyles[color]}`}>{part}</mark>;})}</>}
function ComparisonPreview({columns,start,end,onClose}:{columns:PreviewColumn[];start:number;end:number;onClose:()=>void}){const numbers=Array.from(new Set(columns.flatMap(column=>column.versiculos.filter(verse=>verse.versiculo>=start&&verse.versiculo<=end).map(verse=>verse.versiculo)))).sort((a,b)=>a-b);const keywords=sharedKeywords(columns,start,end);return <section id="bible-comparison-view" className="mb-4 overflow-hidden rounded-[1.35rem] border border-[#D4AF37]/25 bg-[#0B0B0B] landscape:fixed landscape:inset-0 landscape:z-[80] landscape:m-0 landscape:flex landscape:h-[100dvh] landscape:flex-col landscape:rounded-none"><div className="relative border-b border-[#D4AF37]/20 p-4 landscape:py-2"><button type="button" onClick={onClose} aria-label="Cerrar comparación y permitir orientación vertical" className="absolute right-3 top-3 flex h-9 w-9 items-center justify-center rounded-full border border-[#D4AF37]/30 bg-black/50 text-[#F2D27A]"><X className="h-4 w-4"/></button><p className="pr-12 text-[10px] font-semibold uppercase tracking-[0.2em] text-[#D4AF37]">Comparación del pasaje</p><h2 className="mt-1 pr-12 font-display text-xl text-[#F8F5EA] landscape:text-lg">Textos de las versiones bíblicas</h2>{keywords.size>0&&<div className="mt-3 flex flex-wrap gap-2">{[...keywords].slice(0,12).map(([word,color])=><span key={word} className={`rounded-sm border-b px-2 py-1 text-[11px] font-semibold ${keywordStyles[color]}`}><span className="mr-1 opacity-70">{keywordPhase(color)} ·</span><span className="capitalize">{word}</span></span>)}</div>}</div><div className="overflow-x-auto landscape:min-h-0 landscape:flex-1 landscape:overflow-auto"><div className="grid min-w-[36rem] landscape:min-w-0" style={{gridTemplateColumns:`repeat(${columns.length}, minmax(12rem, 1fr))`}}>{columns.map(column=><div key={column.version.codigo} className="border-r border-[#D4AF37]/15 bg-[#111111] p-3 last:border-r-0"><strong className="block text-xs uppercase tracking-wider text-[#D4AF37]">{column.version.abreviatura}</strong><span className="mt-1 block text-[11px] text-[#C9C3B3]">{column.version.nombre} · Capítulo {column.capitulo}</span></div>)}{numbers.map(number=>columns.map(column=>{const verse=column.versiculos.find(item=>item.versiculo===number);return <article key={`${column.version.codigo}-${number}`} className="border-r border-t border-[#D4AF37]/10 p-3 last:border-r-0"><sup className="mr-1.5 font-bold text-[#D4AF37]">{number}</sup><span className="text-sm leading-relaxed text-[#F8F5EA]/90">{verse?<HighlightedVerse text={verse.texto} keywords={keywords}/>:"—"}</span></article>;}))}</div></div></section>}
function StudyView({study,tab,setTab}:{study:BibleStudy;tab:Tab;setTab:(t:Tab)=>void}){
  const d=study.contenido as Data;
  const doctrinalV2=isDoctrinalStudyV2(study.contenido)?study.contenido:null;
  const levelLabel=levelOptions.find(item=>item.value===study.nivel)?.label||"Formador";
  const visibleTabs=tabsForStudyLevel(study.nivel,Boolean(doctrinalV2));
  const activeTab=visibleTabs.includes(tab)?tab:visibleTabs[0];
  const [mobileView,setMobileView]=useState<MobileStudyView>("summary");
  useEffect(()=>setMobileView("summary"),[study.id]);
  useEffect(()=>{if(mobileView==="comparison"&&tab!=="Comparación")setMobileView(tab==="Estructura"?"structure":"text");},[mobileView,tab]);
  const openSection=(next:MobileStudyView)=>{const mapped=mobileTabMap[next];if(mapped)setTab(mapped);setMobileView(next);window.scrollTo({top:0,behavior:"smooth"});};
  const content=<>{activeTab==="Texto"&&<TextTab d={d}/>} {activeTab==="Comparación"&&<ComparisonTab d={d}/>} {activeTab==="Estructura"&&<StructureTab d={d}/>} {activeTab==="Teología"&&(doctrinalV2?<DoctrinalTheologyTab d={doctrinalV2}/>:<TheologyTab d={d}/>)} {activeTab==="Oración"&&<PrayerTab d={d}/>}</>;
  return <>
    <div className="study-mobile-shell md:hidden">
      {mobileView==="summary"&&<StudyMobileSummary study={study} d={d} levelLabel={levelLabel} onContinue={()=>openSection("text")} onText={()=>openSection("text")} onSections={()=>setMobileView("sections")}/>}
      {mobileView==="sections"&&<StudyMobileSections reference={study.referencia} onBack={()=>setMobileView("summary")} onSelect={openSection}/>}
      {!(["summary","sections"] as MobileStudyView[]).includes(mobileView)&&<><StudyMobileHeader reference={study.referencia} title={mobileSectionMeta[mobileView].label} current={mobileSectionOrder.indexOf(mobileView)+1} total={mobileSectionOrder.length} onBack={()=>setMobileView("sections")}/><section className="study-mobile-content min-w-0">{mobileView==="text"&&<TextTab d={d}/>} {mobileView==="comparison"&&<ComparisonTab d={d}/>} {mobileView==="structure"&&<MobileStructureTab d={d}/>} {mobileView==="articulation"&&<ArticulationTable rows={d.articulacion}/>} {mobileView==="arcing"&&<MobileArcingTab d={d}/>} {mobileView==="theology"&&(doctrinalV2?<DoctrinalTheologyTab d={doctrinalV2}/>:<TheologyTab d={d}/>)} {mobileView==="application"&&<ApplicationTab d={d}/>} {mobileView==="lectio"&&<LectioTab d={d}/>}</section><StudySectionPager current={mobileSectionOrder.indexOf(mobileView)} onSelect={openSection}/></>}
    </div>
    <div className="hidden md:block"><StudyDesktopHeader study={study} d={d} levelLabel={levelLabel} doctrinalV2={doctrinalV2}/><nav aria-label="Secciones del estudio" className="study-desktop-tabs mb-3 flex gap-1 rounded-xl border border-[#D4AF37]/20 bg-[#0B0B0B] p-1">{visibleTabs.map(t=><button key={t} type="button" aria-pressed={activeTab===t} onClick={()=>setTab(t)} className={`min-h-11 min-w-0 flex-1 appearance-none rounded-lg border border-transparent px-2 py-2 text-xs outline-none focus-visible:border-[#F2D27A] focus-visible:ring-2 focus-visible:ring-[#D4AF37]/35 ${activeTab===t?"bg-[#D4AF37] font-bold text-black":"text-[#C9C3B3]"}`}>{t}</button>)}</nav><section className="min-w-0 rounded-[1.35rem] border border-[#D4AF37]/20 bg-[#0B0B0B] p-5">{content}</section></div>
  </>;
}

function StudyDesktopHeader({study,d,levelLabel,doctrinalV2}:{study:BibleStudy;d:Data;levelLabel:string;doctrinalV2:DoctrinalStudyV2|null}){return <section className="mb-3 rounded-2xl border border-[#D4AF37]/25 bg-[#0B0B0B] p-4"><div className="flex min-w-0 justify-between gap-3"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><p className="text-xs uppercase tracking-widest text-[#D4AF37]">{study.referencia}</p><span className="rounded-full border border-[#D4AF37]/30 bg-[#D4AF37]/10 px-2 py-1 text-[10px] font-bold uppercase tracking-wider text-[#F2D27A]">Nivel {levelLabel}</span>{doctrinalV2&&<span className="rounded-full border border-white/15 px-2 py-1 text-[10px] text-[#C9C3B3]">Esquema {doctrinalV2.schema_version}</span>}</div><h1 className="mt-2 break-words font-display text-3xl leading-tight">{study.titulo||d.titulo}</h1></div><ShareStudyButton study={study}/></div>{d.comprension_global&&<p className="mt-4 leading-relaxed opacity-90">{d.comprension_global}</p>}{!study.revisado&&<EditorialNotice/>}</section>}

function StudyMobileSummary({study,d,levelLabel,onContinue,onText,onSections}:{study:BibleStudy;d:Data;levelLabel:string;onContinue:()=>void;onText:()=>void;onSections:()=>void}){return <section className="study-mobile-summary min-h-[calc(100dvh-8rem)] pb-5"><div className="flex items-start justify-between gap-3"><div><p className="study-mobile-kicker font-bold uppercase text-[#D4AF37]">{study.referencia}</p><div className="study-mobile-meta mt-3 flex flex-wrap gap-2"><span>Formativo: {levelLabel}</span><span>Integral LVJ</span></div></div><ShareStudyButton study={study}/></div><h1 className="study-mobile-title mt-5 break-words font-display">{study.titulo||d.titulo}</h1><div className="mt-7 space-y-7"><div><h2 className="study-mobile-section-title font-bold text-[#D4AF37]">Resumen</h2><p className="study-mobile-prose mt-3 opacity-90">{d.comprension_global||"El estudio desarrolla la lectura integral del pasaje seleccionado."}</p></div>{d.mensaje_teologico!==undefined&&<div><h2 className="study-mobile-section-title font-bold text-[#D4AF37]">Centro</h2><div className="study-center-note study-mobile-prose mt-3"><StudyValue value={d.mensaje_teologico}/></div></div>}</div>{!study.revisado&&<EditorialNotice/>}<div className="study-summary-actions mt-8 space-y-3"><button type="button" onClick={onContinue} className="flex min-h-12 w-full items-center justify-between rounded-xl bg-[#D4AF37] px-4 text-sm font-bold text-black">Continuar estudio <ChevronRight className="h-4 w-4"/></button><button type="button" onClick={onText} className="study-themed-card flex min-h-12 w-full items-center justify-between rounded-xl border px-4 text-sm font-semibold">Leer texto bíblico <BookOpen className="h-4 w-4 text-[#D4AF37]"/></button><button type="button" onClick={onSections} className="study-themed-card flex min-h-12 w-full items-center justify-between rounded-xl border px-4 text-sm font-semibold">Ver secciones <ChevronRight className="h-4 w-4 text-[#D4AF37]"/></button></div></section>}

type MobileStudyView="summary"|"sections"|"text"|"comparison"|"structure"|"articulation"|"arcing"|"theology"|"application"|"lectio";
const mobileSectionOrder=["text","comparison","structure","articulation","arcing","theology","application","lectio"] as const;
const mobileSectionMeta:Record<(typeof mobileSectionOrder)[number],{label:string;description:string}>={text:{label:"Texto bíblico",description:"Lectura y ajustes"},comparison:{label:"Comparación",description:"Versículo por versículo"},structure:{label:"Estructura",description:"División del pasaje"},articulation:{label:"Articulación",description:"Relaciones y preguntas"},arcing:{label:"Arcing",description:"Escala · Relación · Tipo"},theology:{label:"Teología",description:"Mensaje y contexto"},application:{label:"Aplicación",description:"Vida y meditación"},lectio:{label:"Lectio Divina",description:"Lectura y oración"}};
const mobileTabMap:Partial<Record<MobileStudyView,Tab>>={text:"Texto",comparison:"Comparación",structure:"Estructura",articulation:"Estructura",arcing:"Estructura",theology:"Teología",application:"Oración",lectio:"Oración"};
function StudyMobileSections({reference,onBack,onSelect}:{reference:string;onBack:()=>void;onSelect:(view:MobileStudyView)=>void}){return <section className="min-h-[calc(100dvh-8rem)]"><header className="relative mb-6 text-center"><button type="button" onClick={onBack} className="absolute left-0 flex h-11 w-11 items-center justify-center" aria-label="Volver al resumen"><ArrowLeft className="h-5 w-5"/></button><h1 className="font-display text-xl">Secciones del estudio</h1><p className="mt-1 text-xs text-[#D4AF37]">{reference}</p></header><div className="space-y-3"><button type="button" onClick={()=>onSelect("summary")} className="study-themed-card flex min-h-[4.5rem] w-full items-center gap-3 rounded-xl border p-4 text-left"><span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg border border-[#D4AF37]/25 text-sm font-bold text-[#D4AF37]">1</span><span className="min-w-0 flex-1"><strong className="block text-sm">Resumen</strong><span className="study-themed-muted mt-1 block text-xs">Visión general y centro</span></span><ChevronRight className="h-4 w-4 shrink-0 text-[#D4AF37]"/></button>{mobileSectionOrder.map((item,index)=><button key={item} type="button" onClick={()=>onSelect(item)} className="study-themed-card flex min-h-[4.5rem] w-full items-center gap-3 rounded-xl border p-4 text-left"><span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg border border-[#D4AF37]/25 text-sm font-bold text-[#D4AF37]">{index+2}</span><span className="min-w-0 flex-1"><strong className="block text-sm">{mobileSectionMeta[item].label}</strong><span className="study-themed-muted mt-1 block text-xs">{mobileSectionMeta[item].description}</span></span><ChevronRight className="h-4 w-4 shrink-0 text-[#D4AF37]"/></button>)}</div></section>}

function StudyMobileHeader({reference,title,current,total,onBack}:{reference:string;title:string;current:number;total:number;onBack:()=>void}){return <header className="study-themed-header sticky top-0 z-20 -mx-1 mb-5 border-b px-1 pb-3 pt-1 backdrop-blur"><div className="flex items-center gap-2"><button type="button" onClick={onBack} className="flex h-11 w-11 shrink-0 items-center justify-center" aria-label="Abrir secciones"><ArrowLeft className="h-5 w-5"/></button><div className="min-w-0 flex-1 text-center"><h1 className="truncate font-display text-lg">{title}</h1><p className="text-[11px] text-[#D4AF37]">{reference} · sección {current} de {total}</p></div><span className="h-11 w-11" aria-hidden="true"/></div><div className="mt-2 h-0.5 overflow-hidden rounded-full bg-[#D4AF37]/15"><div className="h-full bg-[#D4AF37]" style={{width:`${current/total*100}%`}}/></div></header>}

function StudySectionPager({current,onSelect}:{current:number;onSelect:(view:MobileStudyView)=>void}){return <nav aria-label="Navegación entre secciones" className="mt-8 grid grid-cols-[1fr_auto_1fr] items-center gap-2 border-t border-[#D4AF37]/20 pt-4"><button type="button" disabled={current<=0} onClick={()=>onSelect(mobileSectionOrder[current-1])} className="min-h-11 text-left text-xs font-semibold text-[#D4AF37] disabled:opacity-30">← Anterior</button><span className="text-xs opacity-60">{current+1} de {mobileSectionOrder.length}</span><button type="button" disabled={current>=mobileSectionOrder.length-1} onClick={()=>onSelect(mobileSectionOrder[current+1])} className="min-h-11 text-right text-xs font-semibold text-[#D4AF37] disabled:opacity-30">Siguiente →</button></nav>}
function ShareStudyButton({study}:{study:BibleStudy}){return <button className="h-11 w-11 shrink-0" aria-label="Compartir" onClick={()=>navigator.share?.({title:study.titulo,text:study.referencia,url:location.href})}><Share2 className="mx-auto h-5 w-5 text-[#D4AF37]"/></button>}
function EditorialNotice(){return <p className="mt-5 rounded-xl border border-[#D4AF37]/15 bg-[#D4AF37]/10 p-3 text-xs text-[#F2D27A]">Contenido pendiente de revisión editorial.</p>}
const Block=({title,children}:{title:string;children:React.ReactNode})=><div className="mb-5 last:mb-0"><h2 className="mb-2 font-display text-lg text-[#D4AF37]">{title}</h2><div className="space-y-2 text-sm leading-relaxed text-[#F8F5EA]/90">{children}</div></div>;
const List=({items}:{items?:unknown[]})=><ul className="list-disc space-y-1 pl-5">{(items||[]).map((x,i)=><li key={i}>{typeof x==="string"?x:JSON.stringify(x)}</li>)}</ul>;
function TextTab({d}:{d:Data}){const labels={platense:"Biblia Platense · Versión principal",torres_amat:"Torres Amat",scio:"Scío de San Miguel"};return <>{(["platense","torres_amat","scio"] as const).map(k=>{const v=d.textos?.[k];return v?<Block key={k} title={labels[k]}><p>{v.disponible?v.texto:v.observacion||"Esta versión no contiene el pasaje equivalente."}</p></Block>:null;})}</>}
function ComparisonTab({d}:{d:Data}){const c=d.comparacion_traducciones||{};const version=(key:string)=>(c[key]||{}) as Comparison;const comparisonKeys=["platense","torres_amat","scio"].filter(key=>version(key).epoca);const stale=Boolean((d as Data&{comparacion_desactualizada?:boolean}).comparacion_desactualizada);if(stale)return <><Block title="Comprensión global"><p>{d.comprension_global}</p></Block><div role="status" className="mb-5 border-l-2 border-amber-300 bg-amber-300/10 p-3 text-sm text-amber-100"><strong>Comparación pendiente de actualización editorial</strong><p className="mt-1 text-amber-100/80">Torres Amat está disponible. Las conclusiones anteriores que indicaban lo contrario fueron ocultadas para no mostrar información desactualizada.</p></div><Block title="Torres Amat · Texto disponible"><p>{d.textos?.torres_amat?.texto}</p></Block></>;return <><Block title="Comprensión global"><p>{d.comprension_global}</p></Block>{comparisonKeys.map(k=><Block key={k} title={k.replace("_"," ")}><p><b>Época:</b> {version(k).epoca}</p><p><b>Estilo:</b> {version(k).estilo}</p><List items={version(k).matices}/></Block>)}<Block title="Coincidencias"><List items={c.coincidencias as string[]}/></Block><Block title="Diferencias relevantes"><List items={c.diferencias_relevantes as string[]}/><p>{c.conclusion as string}</p></Block></>}
function stageTone(stage:string){const value=stage.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase();if(value.includes("inicio"))return "border-amber-300 text-amber-200";if(value.includes("centro"))return "border-cyan-300 text-cyan-200";if(value.includes("consecu"))return "border-violet-300 text-violet-200";if(value.includes("culmin")||value.includes("final"))return "border-rose-300 text-rose-200";return "border-emerald-300 text-emerald-200";}
function ArticulationTable({rows}:{rows?:ArticulationRow[]}){if(!rows?.length)return null;return <Block title="Articulación del texto"><div className="space-y-3 sm:hidden">{rows.map(row=><article key={`${row.orden}-${row.versiculos}`} className="min-w-0 rounded-xl border border-[#D4AF37]/20 p-4"><p className="text-xs font-bold text-[#D4AF37]">{row.versiculos}</p><dl className="mt-3 space-y-3"><MobileField label="Etapa" value={row.etapa}/><MobileField label="Pregunta guía" value={row.pregunta_guia}/><MobileField label="Sujeto principal" value={row.sujeto}/><MobileField label="Verbo central" value={row.verbo_central}/><MobileField label="Desarrollo" value={row.desarrollo}/></dl></article>)}</div><div className="hidden overflow-hidden border-y border-[#D4AF37]/25 sm:block"><div className="grid grid-cols-[4rem_11rem_minmax(0,1fr)] bg-[#D4AF37]/10 text-xs font-bold uppercase tracking-wide"><div className="p-2">Vers.</div><div className="p-2">Acción</div><div className="p-2">Etapa y articulación</div></div>{rows.map(row=><article key={`${row.orden}-${row.versiculos}`} className="grid grid-cols-[4rem_11rem_minmax(0,1fr)] border-t border-[#D4AF37]/15 py-3"><div className="px-2 font-bold text-[#D4AF37]">{row.versiculos}</div><div className="min-w-0 break-words px-2 font-semibold uppercase">{row.verbo_central}</div><div className={`mx-2 min-w-0 border-l-2 pl-3 ${stageTone(row.etapa)}`}><strong className="block break-words uppercase tracking-wide">{row.etapa}</strong><em className="block break-words opacity-75">{row.pregunta_guia}</em><p className="mt-2 break-words"><b>{row.sujeto}:</b> {row.desarrollo}</p></div></article>)}</div></Block>}
function MobileField({label,value}:{label:string;value?:string}){if(!value)return null;return <div className="min-w-0"><dt className="text-[11px] font-bold uppercase tracking-[0.12em] text-[#D4AF37]">{label}</dt><dd className="mt-1 break-words leading-relaxed">{value}</dd></div>}
function ArcingView({data}:{data:ArcData}){return <Block title="Arcing: relaciones lógico-literarias"><div className="mb-4 grid gap-3 sm:grid-cols-2"><p className="min-w-0 break-words rounded-xl border border-[#D4AF37]/20 p-3"><b className="block text-xs uppercase tracking-wide text-[#D4AF37]">Proposición dominante</b>{data.proposicion_dominante}</p><p className="min-w-0 break-words rounded-xl border border-[#D4AF37]/20 p-3"><b className="block text-xs uppercase tracking-wide text-[#D4AF37]">Centro</b>{data.centro}</p></div><div className="space-y-3 sm:hidden">{data.relaciones.map(row=><article key={row.id} className="min-w-0 rounded-xl border border-[#D4AF37]/20 p-4"><dl className="space-y-3"><MobileField label="Escala" value={row.escala}/><MobileField label="Relación" value={`${row.desde} → ${row.hasta}${row.etiqueta?` · ${row.etiqueta}`:""}`}/><MobileField label="Tipo" value={row.tipo}/><MobileField label="Explicación" value={row.explicacion}/><MobileField label="Confianza" value={`${row.confianza}${row.revision?` · ${row.revision}`:""}`}/></dl></article>)}</div><div className="hidden overflow-x-auto sm:block"><table className="w-full min-w-[42rem] border-collapse text-left text-xs"><thead><tr className="border-b border-[#D4AF37]/30 text-[#D4AF37]"><th className="p-2">Escala</th><th className="p-2">Relación</th><th className="p-2">Tipo</th><th className="p-2">Justificación textual</th><th className="p-2">Control</th></tr></thead><tbody>{data.relaciones.map(row=><tr key={row.id} className="border-b border-white/10 align-top"><td className="p-2 font-bold uppercase text-[#F2D27A]">{row.escala}</td><td className="p-2">{row.desde} → {row.hasta}<span className="block text-[#C9C3B3]">{row.etiqueta}</span></td><td className="p-2">{row.tipo}</td><td className="p-2 leading-relaxed">{row.explicacion}</td><td className="p-2">{row.confianza}<span className="block text-[#C9C3B3]">{row.revision}</span></td></tr>)}</tbody></table></div></Block>}
function StructureTab({d}:{d:Data}){const reading=d.lectura_comprension;const unit=d.verificacion_unidad;const arcing=(d as Data&{arcing?:ArcData}).arcing;return <>
  {reading&&<Block title="1. Lectura y comprensión adecuada"><p>{reading.lectura_inicial}</p><p><b>Movimiento:</b> {reading.movimiento_general}</p><List items={[...(reading.conexiones||[]).map(x=>`Conexión: ${x}`),...(reading.oposiciones||[]).map(x=>`Oposición: ${x}`)]}/></Block>}
  {(d.reescritura_comparacion||[]).length>0&&<Block title="2 y 3. Reescritura y comparación"><div className="overflow-x-auto"><table className="min-w-[54rem] w-full border-collapse text-left text-xs"><thead><tr className="border-b border-[#D4AF37]/30 text-[#D4AF37]"><th className="p-2">Referencia</th><th className="p-2">Biblia Platense</th><th className="p-2">Torres Amat</th><th className="p-2">Scío de San Miguel</th><th className="p-2">Observación</th></tr></thead><tbody>{d.reescritura_comparacion!.map((row,index)=>{const scio=(row as typeof row&{scio?:string}).scio;return <tr key={`${row.referencia}-${index}`} className="border-b border-white/10 align-top"><th className="p-2 text-[#F2D27A]">{row.referencia}</th><td className="p-2 leading-relaxed">{row.platense}</td><td className="p-2 leading-relaxed">{row.torres_amat}</td><td className="p-2 leading-relaxed">{scio||d.textos?.scio?.observacion||"Texto de Scío en revisión."}</td><td className="p-2 leading-relaxed text-[#C9C3B3]">{row.observacion}</td></tr>})}</tbody></table></div></Block>}
  <Block title="4. Delimitación y unidad"><p>{d.delimitacion?.unidad}</p><p>{d.delimitacion?.justificacion}</p>{unit&&<><p><b>Inicio:</b> {unit.inicio}</p><p><b>Final:</b> {unit.fin}</p><List items={unit.criterios}/><p>{unit.conclusion}</p></>}</Block>
  <Block title="Género literario"><p><b>{d.genero_literario?.tipo}</b></p><p>{d.genero_literario?.explicacion}</p></Block>
  {d.analisis_proposiciones?<PropositionAnalysisSection data={d.analisis_proposiciones}/>:<Block title="Proposiciones"><List items={(d.proposiciones||[]).map(x=>`${x.tipo}: ${x.texto} — ${x.explicacion}`)}/></Block>}
  {arcing&&<ArcingView data={arcing}/>}
  <ArticulationTable rows={d.articulacion}/>
  <TextStructureView rows={(d.estructura||[]).map((row,index)=>({orden:String(index+1),versiculos:row.versiculos,etapa:row.titulo,pregunta_guia:"",sujeto:"",verbo_central:row.titulo,desarrollo:row.explicacion} satisfies StructureRow))}/>
  {(d.semantica_texto||[]).length>0?<Block title="Semántica del texto"><div className="space-y-3">{d.semantica_texto!.map((row,index)=><div key={`${row.termino}-${index}`} className="border-l-2 border-[#D4AF37]/50 pl-3"><strong className="text-[#D4AF37]">{row.termino}</strong><span className="ml-2 text-xs text-[#C9C3B3]">{row.versiculos}</span><p>{row.sentido_contextual}</p><p className="text-[#C9C3B3]">{row.funcion_en_unidad}</p></div>)}</div></Block>:<Block title="Palabras clave"><List items={(d.palabras_clave||[]).map(x=>`${x.termino}: ${x.significado}. ${x.funcion_en_el_texto}`)}/></Block>}
</>}
function MobileStructureTab({d}:{d:Data}){const unit=d.verificacion_unidad;return <>
  <TextStructureView rows={(d.estructura||[]).map((row,index)=>({orden:String(index+1),versiculos:row.versiculos,etapa:row.titulo,pregunta_guia:"",sujeto:"",verbo_central:row.titulo,desarrollo:row.explicacion} satisfies StructureRow))}/>
  <Block title="Delimitación y unidad"><p>{d.delimitacion?.unidad}</p><p>{d.delimitacion?.justificacion}</p>{unit&&<><p><b>Inicio:</b> {unit.inicio}</p><p><b>Final:</b> {unit.fin}</p><List items={unit.criterios}/><p>{unit.conclusion}</p></>}</Block>
  <Block title="Género literario"><p><b>{d.genero_literario?.tipo}</b></p><p>{d.genero_literario?.explicacion}</p></Block>
  {d.analisis_proposiciones?<PropositionAnalysisSection data={d.analisis_proposiciones}/>:<Block title="Proposiciones"><List items={(d.proposiciones||[]).map(x=>`${x.tipo}: ${x.texto} — ${x.explicacion}`)}/></Block>}
  {(d.semantica_texto||[]).length>0?<Block title="Semántica del texto"><div className="space-y-3">{d.semantica_texto!.map((row,index)=><div key={`${row.termino}-${index}`} className="border-l-2 border-[#D4AF37]/50 pl-3"><strong className="text-[#D4AF37]">{row.termino}</strong><span className="ml-2 text-xs opacity-70">{row.versiculos}</span><p>{row.sentido_contextual}</p><p className="opacity-75">{row.funcion_en_unidad}</p></div>)}</div></Block>:<Block title="Palabras clave"><List items={(d.palabras_clave||[]).map(x=>`${x.termino}: ${x.significado}. ${x.funcion_en_el_texto}`)}/></Block>}
</>}
function MobileArcingTab({d}:{d:Data}){const arcing=(d as Data&{arcing?:ArcData}).arcing;return arcing?<ArcingView data={arcing}/>:<Block title="Arcing / Relaciones"><p>Información no disponible.</p></Block>}
function StudyValue({value}:{value:unknown}){if(value===null||value===undefined||value==="")return <p className="text-[#8F897C]">Información no disponible.</p>;if(typeof value==="string"||typeof value==="number"||typeof value==="boolean")return <p>{typeof value==="boolean"?(value?"Sí":"No"):String(value)}</p>;if(Array.isArray(value))return <ul className="list-disc space-y-2 pl-5">{value.map((item,index)=><li key={index}>{typeof item==="object"&&item!==null?<StudyValue value={item}/>:String(item)}</li>)}</ul>;if(typeof value==="object")return <div className="space-y-3">{Object.entries(value as Record<string,unknown>).map(([key,item])=><div key={key} className="border-l-2 border-[#D4AF37]/35 pl-3"><h3 className="mb-1 text-xs font-bold uppercase tracking-wider text-[#F2D27A]">{key.replaceAll("_"," ")}</h3><StudyValue value={item}/></div>)}</div>;return null;}
function TheologyTab({d}:{d:Data}){return <>{d.contexto_historico!==undefined&&<Block title="Contexto histórico"><StudyValue value={d.contexto_historico}/></Block>}<Block title="Contexto bíblico"><StudyValue value={d.contexto_biblico}/></Block><Block title="Mensaje teológico"><StudyValue value={d.mensaje_teologico}/></Block><Block title="Lectura cristológica"><StudyValue value={d.mensaje_cristologico}/></Block>{d.tipologia!==undefined&&<Block title="Tipología"><StudyValue value={d.tipologia}/></Block>}{d.doctrina_catolica!==undefined&&<Block title="Doctrina católica"><StudyValue value={d.doctrina_catolica}/></Block>}<Block title="Referencias cruzadas"><List items={(d.referencias_cruzadas||[]).map(x=>`${x.referencia}: ${x.relacion}`)}/></Block>{d.actualizacion_pastoral!==undefined&&<Block title="Actualización pastoral"><StudyValue value={d.actualizacion_pastoral}/></Block>}</>}
function DoctrinalTheologyTab({d}:{d:DoctrinalStudyV2}){const doctrine=d.doctrina_catolica;return <><Block title="Fundamentación Straubinger"><StudyValue value={d.fundamentacion_straubinger}/></Block><Block title="Comprensión global"><StudyValue value={d.comprension_global}/></Block><Block title="Contexto bíblico"><StudyValue value={d.contexto_biblico}/></Block><Block title="Mensaje teológico"><StudyValue value={d.mensaje_teologico}/></Block><Block title="Mensaje cristológico"><StudyValue value={d.mensaje_cristologico}/></Block>{d.tipologia&&<Block title="Tipología"><StudyValue value={d.tipologia}/></Block>}<Block title="Doctrina central"><StudyValue value={doctrine.doctrina_central}/></Block><Block title="Catecismo de la Iglesia Católica"><StudyValue value={doctrine.catecismo}/></Block><Block title="Magisterio"><StudyValue value={doctrine.magisterio}/></Block><Block title="Padres de la Iglesia"><StudyValue value={doctrine.padres_iglesia}/></Block>{doctrine.liturgia!==undefined&&<Block title="Liturgia"><StudyValue value={doctrine.liturgia}/></Block>}{doctrine.sacramentos!==undefined&&<Block title="Sacramentos"><StudyValue value={doctrine.sacramentos}/></Block>}<Block title="Moral cristiana"><StudyValue value={doctrine.moral_cristiana}/></Block><Block title="Errores de interpretación"><StudyValue value={doctrine.errores_interpretacion}/></Block><Block title="Referencias cruzadas"><List items={d.referencias_cruzadas.map(x=>`${x.referencia}: ${x.relacion}`)}/></Block><Block title="Advertencias"><List items={d.advertencias}/></Block></>}
function PrayerTab({d}:{d:Data}){return <><Block title="Aplicación espiritual"><p>{d.aplicacion_espiritual}</p></Block><Block title="Preguntas para meditar"><List items={d.preguntas_para_meditar}/></Block>{Object.entries(d.lectio_divina||{}).map(([k,v])=><Block key={k} title={k[0].toUpperCase()+k.slice(1)}><p>{String(v)}</p></Block>)}</>}
function ApplicationTab({d}:{d:Data}){return <><Block title="Aplicación espiritual"><p>{d.aplicacion_espiritual}</p></Block>{d.actualizacion_pastoral!==undefined&&<Block title="Actualización pastoral"><StudyValue value={d.actualizacion_pastoral}/></Block>}<Block title="Preguntas para meditar"><List items={d.preguntas_para_meditar}/></Block></>}
function LectioTab({d}:{d:Data}){return <>{Object.entries(d.lectio_divina||{}).map(([key,value],index)=><Block key={key} title={`${index+1}. ${key.replaceAll("_"," ")}`}><p>{String(value)}</p></Block>)}</>}
